/* eslint-disable eqeqeq */
import { DatePipe } from '@angular/common';
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, IonContent, LoadingController, ToastController } from '@ionic/angular';
import { GAccount } from 'src/app/core/common/GAccount';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { G } from '../../../../core/common/G';
import * as FileSaver from 'file-saver';

@Component({
  selector: 'app-inc',
  templateUrl: './inc.component.html',
  styleUrls: ['./inc.component.scss'],
})
export class IncPage implements OnInit {

  @ViewChild(IonContent) content: IonContent;
  file: any;
  selected = '1';
  form: FormGroup;
  date;

  queryText = '';
  isShow = false;
  isCheck = true;
  isLoading = true;
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  video: string | SafeUrl = 'IcW0q';

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private sanitizer: DomSanitizer,
    public alertController: AlertController,
    public loadingController: LoadingController,
    private siteService: SliderService,
    public toastController: ToastController,
    private courseService: CourseService,
    private datePipe: DatePipe
  ) {
    this.isShow = false;
    if (!GAccount.IsLoggedIn()) {
      this.router.navigateByUrl('/Account');
    }
    this.check();
  }

  async check() {

    this.isLoading = true;

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(18).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit() {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.video = G.IncVideo;

    this.form = this.fb.group({
      v: [5.00, [Validators.required, Validators.min(0.01), Validators.max(24)]],
      ohm: [2490, [Validators.required, Validators.min(0.01), Validators.max(2000000)]]
    });
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.video +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.video;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  reset() {

    this.selected = '1';
    this.file = null;

    this.form.setValue({
      v: 5.00,
      ohm: 2490
    });
  }

  fileChanged(e) {
    this.file = e.target.files[0];
  }

  uploadDocument() {

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          const fileReader = new FileReader();
          fileReader.onload = (e) => {

            let file = fileReader.result.toString();

            let lines = file.split(/\r\n|\r|\t|\n/g);
            let count = 2;

            let volts = [];
            let degrees = [];
            let res = '';

            lines.forEach(s => {

              switch (this.selected) {
                case '1':
                  if (count % 2 == 0) {
                    volts.push((+this.form.value.v * (+s / (+s + +this.form.value.ohm))).toFixed(3));
                  } else {
                    degrees.push(((+s * 1.8) + 32).toFixed(1));
                  }
                  break;
                case '2':
                  if (count % 2 == 0) {
                    volts.push((+this.form.value.v * (+s / (+s + +this.form.value.ohm))).toFixed(3));
                  } else {
                    degrees.push(+s);
                  }
                  break;
                case '3':
                  if (count % 2 == 0) {
                    volts.push(+s);
                  } else {
                    degrees.push(((+s * 1.8) + 32).toFixed(1));
                  }
                  break;

                default:
                  SharedIonic.toast(this.toastController, 'نوع فایل صحیح انتخاب نشده است');
                  return;
              }

              count++;
            });

            for (let i = 0; i < volts.length; i++) {

              res += volts[i];
              res += '\t';
              res += degrees[i];
              res += '\n';
            }

            this.date = new Date();
            const latestDate = this.datePipe.transform(this.date, 'yyyy-MM-dd');
            const latestDateDetail = this.datePipe.transform(this.date, 'yyyy-MM-dd-h-mm-ss');

            try {
              const blob = new Blob([res], { type: 'text;charset=utf-8' });
              FileSaver.saveAs(blob, 'Custom Inc - ' + latestDateDetail + '.inc');
            } catch (e) {
              SharedIonic.toast(this.toastController, 'مرورگر شما از این قابلیت پشتیبانی نمی کند');
            }
          };
          fileReader.readAsText(this.file);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  onBack() {

    this.isShow = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  onInfo(type: string) {

    switch (type) {
      case 'v':
        this.presentActiveAlertConfirm('ولتاژ مرجع سنسور برحسب ولت (V)');
        break;
      case 'ohm':
        this.presentActiveAlertConfirm('مقاومت بایوس داخلی ایسیو برحسب اهم (ohm)');
        break;

      default:
        break;
    }
  }
}
